#!/usr/bin/env python3
"""miniredis: a small threaded TCP key/value server with a line protocol.

Commands (one per line, terminated by \\r\\n or \\n):
    SET key value      -> +OK
    GET key            -> bulk string ($len\\r\\nvalue\\r\\n) or $-1
    DEL key            -> :1 / :0
    INCR key           -> :N  (new value) or -ERR if not an integer
    EXPIRE key seconds -> :1 / :0
    TTL key            -> :seconds / :-1 (no expiry) / :-2 (missing)

Errors are replied to as -ERR <message>.

Expiry is enforced lazily on access and additionally by a background
sweeper thread. The store is guarded by a single lock. The process shuts
down cleanly (exit code 0) on SIGTERM.
"""

from __future__ import annotations

import math
import signal
import socket
import sys
import threading
import time

CRLF = b"\r\n"


class Store:
    """Thread-safe key/value store with lazy + swept expiry."""

    def __init__(self, sweep_interval: float = 0.05):
        self._data: dict[str, str] = {}
        self._expiry: dict[str, float] = {}  # key -> monotonic deadline
        self._lock = threading.Lock()
        self._sweep_interval = sweep_interval
        self._stop = threading.Event()
        self._sweeper: threading.Thread | None = None

    # -- internal helpers (call with lock held) ---------------------------

    def _live(self, key: str) -> bool:
        """Return True if key exists and has not expired; purge if expired."""
        deadline = self._expiry.get(key)
        if deadline is not None and time.monotonic() >= deadline:
            self._data.pop(key, None)
            self._expiry.pop(key, None)
        return key in self._data

    # -- public operations -------------------------------------------------

    def set(self, key: str, value: str) -> None:
        with self._lock:
            self._data[key] = value
            self._expiry.pop(key, None)  # SET clears any TTL

    def get(self, key: str) -> str | None:
        with self._lock:
            if not self._live(key):
                return None
            return self._data[key]

    def delete(self, key: str) -> int:
        with self._lock:
            existed = self._live(key)
            self._data.pop(key, None)
            self._expiry.pop(key, None)
            return 1 if existed else 0

    def incr(self, key: str) -> int:
        with self._lock:
            if self._live(key):
                current = self._data[key]
                try:
                    value = int(current)
                except ValueError:
                    raise ValueError(
                        f"value at '{key}' is not an integer"
                    ) from None
            else:
                value = 0
            value += 1
            self._data[key] = str(value)
            return value

    def expire(self, key: str, seconds: int) -> int:
        if seconds <= 0:
            raise ValueError("EXPIRE requires a positive number of seconds")
        with self._lock:
            if not self._live(key):
                return 0
            self._expiry[key] = time.monotonic() + seconds
            return 1

    def ttl(self, key: str) -> int:
        with self._lock:
            if not self._live(key):
                return -2
            deadline = self._expiry.get(key)
            if deadline is None:
                return -1
            remaining = deadline - time.monotonic()
            return max(0, math.ceil(remaining))

    # -- background sweeper --------------------------------------------------

    def start_sweeper(self) -> None:
        self._sweeper = threading.Thread(
            target=self._sweep_loop, name="sweeper", daemon=True
        )
        self._sweeper.start()

    def _sweep_loop(self) -> None:
        while not self._stop.wait(self._sweep_interval):
            now = time.monotonic()
            with self._lock:
                expired = [k for k, d in self._expiry.items() if now >= d]
                for k in expired:
                    self._data.pop(k, None)
                    self._expiry.pop(k, None)

    def stop_sweeper(self) -> None:
        self._stop.set()


class MiniRedisServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0):
        self.store = Store()
        self.host = host
        self.port = port
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._sock.bind((host, port))
        self.port = self._sock.getsockname()[1]
        self._sock.listen(128)
        self._sock.settimeout(0.2)
        self._stop = threading.Event()
        self._threads: list[threading.Thread] = []

    # -- protocol handling -----------------------------------------------

    @staticmethod
    def handle_command(store: Store, line: str) -> bytes:
        """Execute one command line, returning the full wire reply."""
        if not line.strip():
            return b"-ERR empty command" + CRLF
        head = line.split(None, 1)[0].upper()

        try:
            if head == "SET":
                parts = line.split(None, 2)
                if len(parts) != 3 or not parts[2]:
                    raise ValueError("wrong number of arguments for SET")
                store.set(parts[1], parts[2])
                return b"+OK" + CRLF

            if head == "GET":
                parts = line.split()
                if len(parts) != 2:
                    raise ValueError("wrong number of arguments for GET")
                value = store.get(parts[1])
                if value is None:
                    return b"$-1" + CRLF
                return (
                    f"${len(value.encode())}".encode()
                    + CRLF
                    + value.encode()
                    + CRLF
                )

            if head == "DEL":
                parts = line.split()
                if len(parts) != 2:
                    raise ValueError("wrong number of arguments for DEL")
                n = store.delete(parts[1])
                return f":{n}".encode() + CRLF

            if head == "INCR":
                parts = line.split()
                if len(parts) != 2:
                    raise ValueError("wrong number of arguments for INCR")
                try:
                    n = store.incr(parts[1])
                except ValueError as exc:
                    raise ValueError(str(exc)) from None
                return f":{n}".encode() + CRLF

            if head == "EXPIRE":
                parts = line.split()
                if len(parts) != 3:
                    raise ValueError("wrong number of arguments for EXPIRE")
                try:
                    seconds = int(parts[2])
                except ValueError:
                    raise ValueError(
                        "EXPIRE seconds must be an integer"
                    ) from None
                n = store.expire(parts[1], seconds)
                return f":{n}".encode() + CRLF

            if head == "TTL":
                parts = line.split()
                if len(parts) != 2:
                    raise ValueError("wrong number of arguments for TTL")
                n = store.ttl(parts[1])
                return f":{n}".encode() + CRLF

            raise ValueError(f"unknown command '{head}'")
        except ValueError as exc:
            return f"-ERR {exc}".encode() + CRLF

    # -- connection / lifecycle --------------------------------------------

    def _serve_connection(self, conn: socket.socket) -> None:
        with conn:
            rfile = conn.makefile("rb")
            wfile = conn.makefile("wb")
            try:
                while not self._stop.is_set():
                    raw = rfile.readline()
                    if not raw:
                        break  # client closed the connection
                    line = raw.decode("utf-8", "replace").rstrip("\r\n")
                    reply = self.handle_command(self.store, line)
                    wfile.write(reply)
                    wfile.flush()
            except (ConnectionError, OSError):
                pass
            finally:
                try:
                    rfile.close()
                    wfile.close()
                except OSError:
                    pass

    def serve_forever(self) -> None:
        self.store.start_sweeper()
        while not self._stop.is_set():
            try:
                conn, _addr = self._sock.accept()
            except socket.timeout:
                continue
            except OSError:
                break  # listening socket closed
            t = threading.Thread(
                target=self._serve_connection,
                args=(conn,),
                name="client-conn",
                daemon=True,
            )
            t.start()
            self._threads.append(t)
        self.shutdown()

    def request_stop(self, *_args) -> None:
        self._stop.set()

    def shutdown(self) -> None:
        self._stop.set()
        self.store.stop_sweeper()
        try:
            self._sock.close()
        except OSError:
            pass
        # Give worker threads a moment to finish their in-flight replies.
        deadline = time.monotonic() + 2.0
        for t in list(self._threads):
            t.join(timeout=max(0.0, deadline - time.monotonic()))
        self._threads.clear()


def main(argv: list[str]) -> int:
    port = int(argv[1]) if len(argv) > 1 else 6379
    server = MiniRedisServer(port=port)
    print(f"miniredis listening on {server.host}:{server.port}", flush=True)

    def on_sigterm(_signum, _frame):
        server.request_stop()

    signal.signal(signal.SIGTERM, on_sigterm)
    signal.signal(signal.SIGINT, on_sigterm)

    try:
        server.serve_forever()
    finally:
        print("miniredis shut down cleanly", flush=True)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))

