"""Small client library for miniredis."""

from __future__ import annotations

import socket


class MiniRedisError(Exception):
    """Raised when the server replies with an -ERR error."""


class ConnectionClosed(MiniRedisError):
    """Raised when the server closes the connection."""


class MiniRedisClient:
    def __init__(self, host: str = "127.0.0.1", port: int = 6379, timeout: float = 10.0):
        self.host = host
        self.port = port
        self.timeout = timeout
        self._sock: socket.socket | None = None
        self._rfile = None
        self._wfile = None

    # -- connection management ---------------------------------------------

    def connect(self) -> "MiniRedisClient":
        if self._sock is None:
            self._sock = socket.create_connection((self.host, self.port), timeout=self.timeout)
            self._rfile = self._sock.makefile("rb")
            self._wfile = self._sock.makefile("wb")
        return self

    def close(self) -> None:
        if self._sock is not None:
            try:
                self._wfile.close()
                self._rfile.close()
            finally:
                self._sock.close()
                self._sock = None
                self._rfile = None
                self._wfile = None

    def __enter__(self) -> "MiniRedisClient":
        return self.connect()

    def __exit__(self, *exc_info) -> None:
        self.close()

    # -- low-level protocol ---------------------------------------------------

    def execute(self, command: str):
        """Send one command line, parse and return the reply."""
        self.connect()
        assert self._rfile is not None and self._wfile is not None
        try:
            self._wfile.write(command.rstrip("\r\n").encode() + b"\r\n")
            self._wfile.flush()
            raw = self._rfile.readline()
        except (BrokenPipeError, ConnectionResetError):
            self.close()
            raise ConnectionClosed("connection lost while sending") from None
        if not raw:
            self.close()
            raise ConnectionClosed("connection closed by server")
        line = raw.decode().rstrip("\r\n")

        if line.startswith("+"):
            return line[1:]
        if line.startswith("-"):
            raise MiniRedisError(line[1:])
        if line.startswith(":"):
            return int(line[1:])
        if line.startswith("$"):
            length = int(line[1:])
            if length == -1:
                return None
            data = self._rfile.read(length + 2)  # payload + trailing CRLF
            if data is None or len(data) < length:
                self.close()
                raise ConnectionClosed("connection closed mid-reply")
            return data[:length].decode()
        raise MiniRedisError(f"malformed reply: {line!r}")

    # -- typed convenience API --------------------------------------------------

    def set(self, key: str, value: str) -> bool:
        return self.execute(f"SET {key} {value}") == "OK"

    def get(self, key: str) -> str | None:
        return self.execute(f"GET {key}")

    def delete(self, key: str) -> int:
        return self.execute(f"DEL {key}")

    def incr(self, key: str) -> int:
        return self.execute(f"INCR {key}")

    def expire(self, key: str, seconds: int) -> int:
        return self.execute(f"EXPIRE {key} {seconds}")

    def ttl(self, key: str) -> int:
        return self.execute(f"TTL {key}")

